const ALLOWED = ['record_transaction', 'financial_setup', 'financial_insight'];

// 1. Read the answer text from the OpenAI output structure, without fixed indexes
function readText(data) {
  const out = Array.isArray(data.output) ? data.output : [];
  for (const item of out) {
    for (const c of (item.content || [])) {
      if (typeof c.text === 'string') return c.text;
    }
  }
  return '';
}

// 2. Strip markdown fences if the model added them
let raw = readText($json).trim();
raw = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');

// 3. Parse safely: on failure, treat as no intent
let intents = [];
try {
  const parsed = JSON.parse(raw);
  const list = Array.isArray(parsed) ? parsed : parsed.intents;
  if (Array.isArray(list)) intents = list;
} catch (e) {
  intents = [];
}

// 4. Keep only known intents, drop duplicates
intents = [...new Set(intents.filter(i => ALLOWED.includes(i)))];

// 5. Safety net: financial_setup next to record_transaction must be backed by real setup wording in the message
//    (a management verb, a setup field, or a clause that starts with budget/akun/savings/target).
//    "makan bakso 25rb pakai BCA tanggal 20 oktober" mentions an account but is only a transaction.
const msg = String($('Data Input').first().json.message || '').toLowerCase();
const SETUP_HINT = /\b(buat|bikin|create|add|tambah|tambahin|kurangi|naikkan|naikin|turunkan|turunin|increase|decrease|deduct|set|atur|ubah|ganti|update|change|edit|rename|hapus|delete|remove|target|limit|deadline|saldo awal|tipe|nama akun)\b|(^|[,;.]|\bdan\b|\bterus\b|\blalu\b)\s*(budget|akun|account|rekening|savings|target)\b/;
if (intents.includes('record_transaction') && intents.includes('financial_setup') && !SETUP_HINT.test(msg)) {
  intents = intents.filter(i => i !== 'financial_setup');
}

// 6. Hypothetical questions ("kalau aku beli laptop 15jt, budgetku aman?") are insight only. Nothing is recorded or changed.
//    Drop record_transaction / financial_setup when EVERY clause that holds an amount is phrased as "kalau / what if".
if (intents.includes('financial_insight') && (intents.includes('record_transaction') || intents.includes('financial_setup'))) {
  const HYPO = /\b(kalau|kalo|jika|seandainya|andai|bagaimana jika|gimana kalau|gimana kalo|what if|if i)\b/;
  const AMOUNT = /\d[\d.,]*\s*(rb|ribu|k|jt|juta|m)?\b/;
  const clauses = msg.split(/[,;.?!]|\bdan\b|\bterus\b|\blalu\b/).filter(c => AMOUNT.test(c));
  if (clauses.length > 0 && clauses.every(c => HYPO.test(c))) {
    intents = intents.filter(i => i === 'financial_insight');
  }
}

// 7. Advice questions ("enaknya nama budget apa ya?", "sebaiknya berapa?") are insight only.
//    They contain no amount, so there is nothing to create or record. Without this, "buat budget ..." in the
//    question makes setup run and reply "Data budget belum lengkap".

const ADVICE =
/\b(enaknya|enakan|sebaiknya|baiknya|bagusnya|cocoknya|saran|sarankan|rekomendasi|rekomendasikan|rekomendasiin|usul|usulkan|menurutmu|menurut|suggest|better|pendapat|opini|mending|lebih baik|pilihin|pilih yang mana|kasih ide|ada ide|ide lain|alternatif|inspirasi|worth it|layak nggak|should i|what do you think|what's your take|what is your opinion|suggest|recommend)\b|\b(apa|gimana|bagaimana)\s+ya\b|\bnama\b.{0,25}\bapa\b|\bgimana menurut\b|\bbagaimana menurut\b|\bbagaimana kalau\b/;

const HAS_AMOUNT = /\d[\d.,]*\s*(rb|ribu|k|jt|juta|m)?\b/;
if (ADVICE.test(msg) && !HAS_AMOUNT.test(msg)) {
  intents = ['financial_insight'];
}

return [{ json: { intents, raw_output: raw } }];

const intents = $json.intents || [];

if (intents.length === 0) {
  return [
    {
      json: {
        intent: "unmatched"
      }
    }
  ];
}

return intents.map(intent => ({
  json: {
    intent: intent
  }
}));

