const setupItems = $("Check Validation (B)")
  .all()
  .filter(i => i.json.valid_status === "valid");
const rows = $("Merge (B)").all().map(i => i.json);

const rp = (n) => "Rp" + new Intl.NumberFormat("id-ID").format(Number(n ?? 0));
const same = (a, b) => a != null && b != null && String(a).toLowerCase() === String(b).toLowerCase();

const out = [];
for (const item of setupItems) {
  const data = item.json;
  const action = data.action;

  // cocokkan lewat nama (bukan urutan), supaya item yang ditolak tidak menggeser yang lain
  const b = rows.find(r => same(r.old_category ?? r.category, data.name) || same(r.category, data.name));
  if (!b) continue; // ditolak validasi: node warning sudah membalas

  const lines = [];

  if (action === "create") {
    lines.push("✅ Budget dibuat", "");
    lines.push(`📂 Category: ${b.category}`);
    lines.push(`💰 Limit: ${rp(b.limit_amount)}`);

  } else if (action === "increase" || action === "decrease") {
    const up = action === "increase";
    const delta = Number(data.amount ?? 0);
    const newLimit = Number(b.limit_amount);
    const oldLimit = up ? newLimit - delta : newLimit + delta;

    lines.push(up ? "✅ Budget dinaikkan" : "✅ Budget diturunkan", "");
    lines.push(`📂 Category: ${b.category}`);
    lines.push(`💰 Limit: ${rp(oldLimit)} ➜ ${rp(newLimit)} (${up ? "+" : "-"}${rp(delta)})`);

  } else if (action === "update") {
    const oldName = b.old_category ?? data.name;
    const oldLimit = Number(b.old_limit_amount ?? b.limit_amount);
    const newLimit = Number(b.limit_amount);
    const nameChanged = oldName !== b.category;
    const limitChanged = oldLimit !== newLimit;

    // perubahan relatif (naikkan/kurangi) yang dilipat ke update ini
    const delta = Number(data.amount_delta ?? 0);
    const showDelta = delta !== 0 && data.new_amount == null;
    const deltaText = showDelta ? ` (${delta > 0 ? "+" : "-"}${rp(Math.abs(delta))})` : "";

    lines.push("✅ Budget diperbarui", "");
    lines.push(`📂 Category: ${nameChanged ? `${oldName} ➜ ${b.category}` : b.category}`);
    lines.push(`💰 Limit: ${limitChanged ? `${rp(oldLimit)} ➜ ${rp(newLimit)}${deltaText}` : rp(newLimit)}`);
    if (!nameChanged && !limitChanged) {
      lines.push("", "ℹ️ Datanya sama dengan sebelumnya, tidak ada yang berubah.");
    }

  } else if (action === "delete") {
    lines.push("🗑️ Budget dihapus", "");
    lines.push(`📂 Category: ${b.category}`);
    lines.push(`💰 Limit terakhir: ${rp(b.limit_amount)}`);

  } else {
    lines.push("✅ Selesai");
  }

  out.push({ json: { action, message: lines.join("\n") } });
}
return out;

const raw = $json.output?.[0]?.content?.[0]?.text ?? '';
const text = String(raw).replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();

let parsed;
try { parsed = JSON.parse(text); } catch (e) { parsed = null; }

const list = (Array.isArray(parsed) ? parsed : [parsed]).filter(x => x && typeof x === 'object');

// If parsing fails or returns an empty result, route to the fallback path so the user still receives a response
if (list.length === 0) {
  return [{ json: { entity: null, action: null, name: null, raw_output: text } }];
}

const rawMsg = String($('Data Input').first().json.message || '');
const msg = rawMsg.toLowerCase();

const CREATE_WORD = /\b(buat|buatkan|buatin|bikin|bikinin|bikinkan|create|make|set|atur|siapkan|setup|set up|daftarkan|baru|new)\b|\b(tambah|tambahkan|tambahin|add)\s+(akun|account|rekening|budget|kategori|savings|tabungan|goal)\b/;
const ADJUST_WORD = /\b(saldo|balance|tambah|tambahin|kurangi|kurangin|naikkan|naikin|turunkan|turunin|increase|decrease|add|reduce|deduct)\b/;
// signs of a NEW account: "saldo awal", or "tipe <type>"
const NEW_ACCOUNT = /saldo awal|initial balance|\b(?:tipe|type|jenis)\w*\s+(?:bank|cash|tunai|e-?\s?wallet|dompet digital|credit\s*card|kartu kredit|loan|pinjaman|other|lainnya)/;
const TYPE_MAP = [[/e-?\s?wallet|dompet digital/, 'e-wallet'], [/credit\s*card|kartu kredit/, 'credit_card'], [/\bcash\b|tunai/, 'cash'],
                  [/\bbank\b/, 'bank'], [/\bloan\b|pinjaman/, 'loan'], [/\bother\b|lainnya/, 'other']];
const typeFrom = it => {
  const tm = msg.match(/\b(?:tipe|type|jenis)\w*\s+([a-z -]+?)(?=\s+(?:saldo|dengan|sebesar|senilai)\b|\s+\d|[,;.]|$)/);
  return it.acc_type || (tm ? (TYPE_MAP.find(([re]) => re.test(tm[1])) || [])[1] : null) || null;
};

// Safety net 1: the AI mixed up adjusting a balance and creating an account.
// "gaji masuk 2jt ke BCA" is income (recorded elsewhere), not a change of the BCA balance.
const kept0 = list.map(it => {
  const isAcc = String(it.entity).toLowerCase() === 'account';
  const act = String(it.action).toLowerCase();
  // AI said "adjust the balance" but the message describes a NEW account -> it is a create
  if (isAcc && ['increase', 'decrease'].includes(act) && NEW_ACCOUNT.test(msg) && CREATE_WORD.test(msg)) {
    return { ...it, action: 'create', acc_type: typeFrom(it) };
  }
  // AI said "create" but the message is "tambahin 10k di akun bca" -> it is a balance increase
  if (isAcc && act === 'create' && !NEW_ACCOUNT.test(msg) && /\b(tambah|tambahin|tambahkan|add)\s+(?:rp\.?\s?)?\d/.test(msg)) {
    return { ...it, action: 'increase' };
  }
  return it;
}).filter(it => !(String(it.entity).toLowerCase() === 'account'
  && ['increase', 'decrease'].includes(String(it.action).toLowerCase()) && !ADJUST_WORD.test(msg)));
if (kept0.length === 0) {
  return [{ json: { entity: null, action: null, name: null, raw_output: text, ignored_as_transaction: true } }];
}

// Safety net 2: "akun BCA Saving tipe bank ..." is an ACCOUNT even though the name contains "saving".
// If the message puts akun/account/rekening right before the name, the entity is account.
const kept = kept0.map(it => {
  if (String(it.entity).toLowerCase() !== 'savings' || String(it.action).toLowerCase() !== 'create' || !it.name) return it;
  const am = rawMsg.match(/\b(?:akun|account|rekening)\s+(?:baru\s+)?([a-z0-9&_-]+(?:\s+[a-z0-9&_-]+)*?)(?=\s+(?:tipe|type|jenis|saldo|dengan|sebesar|senilai)\b|\s+\d|[,;.]|$)/i);
  if (!am) return it;
  const accName = am[1].trim(), a = accName.toLowerCase(), n = String(it.name).trim().toLowerCase();
  if (!(a.includes(n) || n.includes(a))) return it;      // the account word belongs to a different clause
  return { ...it, entity: 'account', name: accName, acc_type: typeFrom(it) };
});

// Safety net 3: creating something new needs an explicit create word (buat, bikin, set, tambah akun ...).
// "BCA Saving tipe bank saldo awal 10jt" has none, so nothing is created and the user gets the help message.
const final = kept.filter(it => !(String(it.action).toLowerCase() === 'create' && !CREATE_WORD.test(msg)));
if (final.length === 0) {
  return [{ json: { entity: null, action: null, name: null, raw_output: text, missing_create_word: true } }];
}
return final.map(item => ({ json: item }));

const BULK = /\b(semua|semuanya|seluruh|segala|all|every|everything)\b/i;
// a name that is only a type word ("savings", "budget", "akun") means the parser dropped "semua"
const TYPE_ONLY = /^(budgets?|kategori|categor(?:y|ies)|savings?|tabungan|goals?|akun|akun-akun|accounts?|rekening)$/i;
let rawMessage = '';
try { rawMessage = String($('Data Input').first().json.message ?? ''); } catch (err) { rawMessage = ''; }
const clauseFor = (name) => {
  const n = String(name ?? '').toLowerCase();
  const parts = rawMessage.split(/[,;\n]|\s+(?:dan|lalu|terus|kemudian|and|then)\s+/i);
  return parts.find(p => n && p.toLowerCase().includes(n)) ?? rawMessage;
};
const isEmpty = (v) => v == null || v === 'null' || v === '';

const existenceItems = $input.all();
const entityItems = $('Check Entities').all();

return existenceItems.map((item, index) => {
  const e = entityItems[index].json;
  const a = e.action;
  const exists = item.json.category_exists;
  const nameStr = isEmpty(e.name) ? '' : String(e.name).trim();

  // value after the change; a change that would push it below 0 is rejected
  const cur = item.json.current_amount == null ? null : Number(item.json.current_amount);
  let nextAmount = null;
  if (cur !== null && (a === 'increase' || a === 'decrease') && !isEmpty(e.amount)) {
    nextAmount = cur + (a === 'decrease' ? -1 : 1) * Number(e.amount);
  } else if (cur !== null && a === 'update' && (!isEmpty(e.new_amount) || !isEmpty(e.amount_delta))) {
    nextAmount = (isEmpty(e.new_amount) ? cur : Number(e.new_amount)) + (Number(e.amount_delta) || 0);
  }


  let reason = null;
  if (a === 'create') {
    if (isEmpty(e.name) || isEmpty(e.amount) || Number(e.amount) <= 0) reason = 'incomplete';
    else if (exists) reason = 'duplicate';
  } else if (isEmpty(e.name)) {
    reason = a === 'delete' ? 'bulk_delete' : 'name_required';
  } else if (a === 'delete' && !exists && (BULK.test(nameStr) || TYPE_ONLY.test(nameStr) || BULK.test(clauseFor(nameStr)))) {
    reason = 'bulk_delete';
  } else if (!exists) {
    reason = 'not_found';
  } else if ((a === 'increase' || a === 'decrease') && isEmpty(e.amount)) {
    reason = 'amount_required';
  } else if (nextAmount !== null && nextAmount < 0) {
    reason = 'below_zero';
  } else if (a === 'update' && isEmpty(e.new_name) && isEmpty(e.new_amount) && isEmpty(e.amount_delta)) {
    reason = 'nothing_to_update';
  } else if (a === 'update' && item.json.new_name_taken) {
    reason = 'duplicate_new';
  }

  return {
    json: {
      ...e, ...item.json,
      valid_status: reason ? 'invalid' : 'valid',
      invalid_reason: reason
    }
  };
});

parameters.text:
={{ (() => {
  const list = $json.categories;
  const rp = (n) => 'Rp' + new Intl.NumberFormat('id-ID').format(Number(n ?? 0));
  const bad = $('Check Validation (B)').all().map(i => i.json).filter(j => j.valid_status === 'invalid');
  if (!bad.length) return '⚠️ Perintah tidak bisa diproses.';

  // exactly one rejected command: a short, specific message
  const single = (j) => {
    const nm = j.name;
    switch (j.invalid_reason) {
      case 'below_zero': return '⚠️ Limit budget "' + nm + '" tidak boleh di bawah Rp0. Limit saat ini ' + rp(j.current_amount) + ', pengurangan ' + rp(j.amount) + ' terlalu besar.\n\nContoh: "kurangi budget ' + nm + ' ' + rp(Math.floor(Number(j.current_amount) / 2)).replace('Rp','').replace(/\./g,'') + '"';
      case 'duplicate': return '⚠️ Budget "' + nm + '" sudah ada. Pakai nama lain, atau ubah budget yang sudah ada.\n\nBudget yang ada:\n' + list + '\n\nContoh: "set budget food jadi 600rb"';
      case 'duplicate_new': return '⚠️ Nama "' + j.new_name + '" sudah dipakai budget lain. Pilih nama yang berbeda.\n\nBudget yang ada:\n' + list;
      case 'incomplete': return '⚠️ Data budget belum lengkap. Sebutkan nama kategori dan limit.\n\nContoh: "buat budget food 500rb"';
      case 'bulk_delete': return '⚠️ Penghapusan massal tidak didukung.\n\nDemi keamanan, budget dihapus satu per satu. Sebutkan namanya.\n\nBudget yang ada:\n' + list + '\n\nContoh: "hapus budget food"';
      case 'name_required': return '⚠️ Sebutkan nama budget yang ingin diubah.\n\nBudget yang ada:\n' + list;
      case 'amount_required': return '⚠️ Nominalnya belum disebutkan.\n\nContoh: "tambah budget ' + (nm ?? 'food') + ' 100rb"';
      case 'nothing_to_update': return 'ℹ️ Tidak ada yang diubah. Sebutkan nama baru atau limit baru.\n\nContoh: "set budget food jadi 600rb"';
      default: return '⚠️ Budget "' + nm + '" tidak ditemukan.\n\nBudget yang ada:\n' + list + '\n\nUntuk membuat baru, tulis: "buat budget food 500rb"';
    }
  };

  // several rejected commands: one combined message
  const why = (j) => {
    switch (j.invalid_reason) {
      case 'below_zero': return 'hasil perubahan di bawah Rp0 (limit saat ini ' + rp(j.current_amount) + ')';
      case 'duplicate': return 'nama sudah ada';
      case 'duplicate_new': return 'nama baru "' + j.new_name + '" sudah dipakai budget lain';
      case 'incomplete': return 'data belum lengkap (sebutkan nama dan limit)';
      case 'bulk_delete': return 'penghapusan massal tidak didukung, sebutkan satu nama';
      case 'name_required': return 'nama budget belum disebutkan';
      case 'amount_required': return 'nominal belum disebutkan';
      case 'nothing_to_update': return 'tidak ada yang diubah (sebutkan nama baru atau limit baru)';
      default: return 'tidak ditemukan';
    }
  };

  if (bad.length === 1) return single(bad[0]);

  const hints = {
    not_found: 'Untuk membuat baru, tulis: "buat budget food 500rb"',
    duplicate: 'Contoh: "set budget food jadi 600rb"',
    incomplete: 'Contoh: "buat budget food 500rb"',
    bulk_delete: 'Contoh: "hapus budget food"',
    amount_required: 'Contoh: "tambah budget food 100rb"',
    nothing_to_update: 'Contoh: "set budget food jadi 600rb"'
  };
  const lines = bad.map(j => '• ' + (j.name ? '"' + j.name + '"' : '(tanpa nama)') + ': ' + why(j));
  const hint = hints[bad[0].invalid_reason ?? 'not_found'] ?? '';
  return '⚠️ Beberapa perintah tidak bisa diproses:\n' + lines.join('\n')
    + '\n\nBudget yang ada:\n' + list
    + (hint ? '\n\n' + hint : '');
})() }}

parameters.query:
SELECT category
FROM budgets
ORDER BY category;

INSERT INTO budgets(category, limit_amount)
VALUES (
  '{{ $json.name }}',
  {{ $json.amount }}
)
  RETURNING *;

DELETE FROM budgets
WHERE LOWER(category) = LOWER('{{ $json.name }}')
  RETURNING *;

