const BULK = /\b(semua|semuanya|seluruh|segala|all|every|everything)\b/i;
// a name that is only a type word ("savings", "budget", "akun") means the parser dropped "semua"
const TYPE_ONLY = /^(budgets?|kategori|categor(?:y|ies)|savings?|tabungan|goals?|akun|akun-akun|accounts?|rekening)$/i;
const isEmpty = (v) => v == null || v === 'null' || v === '';

// "create" of a name that already exists, in a clause with no create word
// ("target cobacoba 500000"), is almost certainly an update.
const CREATE_WORDS = /\b(buat|bikin|buatkan|create|make)\b/i;
let rawMessage = '';
try { rawMessage = String($('Data Input').first().json.message ?? ''); } catch (err) { rawMessage = ''; }
const clauseFor = (name) => {
  const n = String(name ?? '').toLowerCase();
  const parts = rawMessage.split(/[,;\n]|\s+(?:dan|lalu|terus|kemudian|and|then)\s+/i);
  return parts.find(p => n && p.toLowerCase().includes(n)) ?? rawMessage;
};

const MONTHS = ['Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni', 'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember'];
const fmtId = (y, m, d) => `${d} ${MONTHS[m - 1]} ${y}`;

// Checks a deadline and fixes what can be fixed safely.
// - not parseable / impossible month or year  -> { value: null }   (rejected)
// - day beyond the month length (31 Feb)       -> clamped to the last day, with a note
// - allowPartial (update): "2028" and "2028-06" are accepted as-is; the DB fills in the rest
const fixDate = (s, allowPartial) => {
  const t = String(s).trim();
  const yearOk = (y) => y >= 1900 && y <= 2200;

  if (allowPartial) {
    if (/^\d{4}$/.test(t)) return { value: yearOk(Number(t)) ? t : null };
    const pm = /^(\d{4})-(\d{2})$/.exec(t);
    if (pm) return { value: yearOk(Number(pm[1])) && Number(pm[2]) >= 1 && Number(pm[2]) <= 12 ? t : null };
  }

  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(t);
  if (!m) return { value: null };
  const y = Number(m[1]), mo = Number(m[2]), d = Number(m[3]);
  if (!yearOk(y) || mo < 1 || mo > 12 || d < 1 || d > 31) return { value: null };

  const last = new Date(Date.UTC(y, mo, 0)).getUTCDate();
  if (d <= last) return { value: t };

  const fixed = `${m[1]}-${m[2]}-${String(last).padStart(2, '0')}`;
  return {
    value: fixed,
    note: `⚠️ Tanggal ${fmtId(y, mo, d)} tidak ada, jadi deadline disesuaikan ke ${fmtId(y, mo, last)}.`
  };
};

const existenceItems = $input.all();
const entityItems = $('Check Entities').all();

const seenCreate = new Set();
return existenceItems.map((item, index) => {
  let e = entityItems[index].json;
  // exact name first; if not found, retry without a leading type word ("savings rumah" -> "rumah")
  const useStripped = !item.json.category_exists && item.json.stripped_exists === true;
  const exists = item.json.category_exists || useStripped;

  // create on an existing name without any "buat/bikin": treat as an update of that field
  if (e.action === 'create' && exists && !CREATE_WORDS.test(clauseFor(e.name))) {
    e = {
      ...e,
      action: 'update',
      new_amount: e.amount,
      new_target_date: e.target_date,
      amount: null,
      target_date: null
    };
  }

  const a = e.action;
  const nameStr = isEmpty(e.name) ? '' : String(e.name).trim();

  // value after the change; a change that would push it below 0 is rejected
  const cur = item.json.current_amount == null ? null : Number(item.json.current_amount);
  let nextAmount = null;
  if (cur !== null && (a === 'increase' || a === 'decrease') && !isEmpty(e.amount)) {
    nextAmount = cur + (a === 'decrease' ? -1 : 1) * Number(e.amount);
  } else if (cur !== null && a === 'update' && (!isEmpty(e.new_amount) || !isEmpty(e.amount_delta))) {
    nextAmount = (isEmpty(e.new_amount) ? cur : Number(e.new_amount)) + (Number(e.amount_delta) || 0);
  }


  let dateFix = null;
  if (a === 'create' && !isEmpty(e.target_date)) dateFix = fixDate(e.target_date, false);
  if (a === 'update' && !isEmpty(e.new_target_date)) dateFix = fixDate(e.new_target_date, true);

  let reason = null;
  if (a === 'create') {
    if (isEmpty(e.name) || isEmpty(e.amount) || Number(e.amount) <= 0) reason = 'incomplete';
    else if (exists || seenCreate.has(nameStr.toLowerCase())) reason = 'duplicate';
    else if (dateFix && dateFix.value == null) reason = 'bad_date';
  } else if (isEmpty(e.name)) {
    reason = a === 'delete' ? 'bulk_delete' : 'name_required';
  } else if (a === 'delete' && !exists && (BULK.test(nameStr) || TYPE_ONLY.test(nameStr) || BULK.test(clauseFor(nameStr)))) {
    reason = 'bulk_delete';
  } else if (!exists) {
    reason = 'not_found';
  } else if ((a === 'increase' || a === 'decrease') && isEmpty(e.amount)) {
    reason = 'amount_required';
  } else if (nextAmount !== null && nextAmount < 0) {
    reason = 'below_zero';
  } else if (a === 'update' && dateFix && dateFix.value == null) {
    reason = 'bad_date';
  } else if (a === 'update' && isEmpty(e.new_name) && isEmpty(e.new_amount) && isEmpty(e.new_target_date) && isEmpty(e.amount_delta)) {
    reason = 'nothing_to_update';
  } else if (a === 'update' && item.json.new_name_taken) {
    reason = 'duplicate_new';
  }

  if (a === 'create' && !reason) seenCreate.add(nameStr.toLowerCase());

  const out = {
    ...e, ...item.json,
    valid_status: reason ? 'invalid' : 'valid',
    invalid_reason: reason
  };

  // downstream nodes use the resolved name
  if (useStripped) out.name = item.json.stripped_name;

  // use the corrected date downstream and remember a note for the reply
  if (!reason && dateFix && dateFix.value != null) {
    if (a === 'create') out.target_date = dateFix.value;
    else out.new_target_date = dateFix.value;
    if (dateFix.note) out.date_note = dateFix.note;
  }

  return { json: out };
});

