      default: return 'tidak ditemukan';
    }
  };

  if (bad.length === 1) return single(bad[0]);

  const hints = {
    not_found: 'Untuk membuat baru, tulis: "buat savings rumah target 200jt"',
    duplicate: 'Contoh: "ubah target savings rumah jadi 250jt"',
