parameters.jsCode:
const setupItems = $("Check Validation (A)")
  .all()
  .filter(i => i.json.valid_status === "valid");
const rows = $("Merge (A)").all().map(i => i.json);

const rp = (n) => "Rp" + new Intl.NumberFormat("id-ID").format(Number(n ?? 0));
const same = (a, b) => a != null && b != null && String(a).toLowerCase() === String(b).toLowerCase();

const ICONS = { bank: "🏦", "e-wallet": "📱", cash: "💵", credit_card: "💳", loan: "🧾", other: "📦" };
const iconFor = (type) => ICONS[String(type ?? "").toLowerCase()] ?? "📦";

return setupItems.map((item) => {
  const data = item.json;
  const action = data.action;

  // cocokkan lewat nama (bukan urutan), supaya item lain tidak menggeser hasilnya
  const acc = rows.find(r => same(r.old_name ?? r.account_name, data.name) || same(r.account_name, data.name));

  if (!acc || !acc.account_id) {
    return {
      json: {
        action,
        message: `⚠️ Tidak ada yang berubah.\n\nAkun "${data.name}" tidak ditemukan atau datanya sama.`
      }
    };
  }

  const icon = iconFor(acc.account_type);
  const lines = [];

  if (action === "create") {
    lines.push("✅ Akun dibuat", "");
    lines.push(`${icon} ${acc.account_name}`);
    lines.push(`🏷️ Tipe: ${acc.account_type}`);
    lines.push(`💰 Saldo: ${rp(acc.balance)}`);

  } else if (action === "increase" || action === "decrease") {
    const up = action === "increase";
    const delta = Number(data.amount ?? 0);
    const newBal = Number(acc.balance);
    const oldBal = up ? newBal - delta : newBal + delta;

    lines.push(up ? "✅ Saldo bertambah" : "✅ Saldo berkurang", "");
    lines.push(`${icon} ${acc.account_name}`);
    lines.push(`🏷️ Tipe: ${acc.account_type}`);
    lines.push(`💰 Saldo: ${rp(oldBal)} ➜ ${rp(newBal)} (${up ? "+" : "-"}${rp(delta)})`);

  } else if (action === "update") {
    const oldName = acc.old_name ?? data.name;
    const oldType = acc.old_type;
    const oldBal = Number(acc.old_balance ?? acc.balance);
    const newBal = Number(acc.balance);

    // perubahan relatif (naikkan/kurangi) yang dilipat ke update ini
    const delta = Number(data.amount_delta ?? 0);
    const showDelta = delta !== 0 && data.new_amount == null;
    const deltaText = showDelta ? ` (${delta > 0 ? "+" : "-"}${rp(Math.abs(delta))})` : "";

    const nameChanged = oldName !== acc.account_name;
    const typeChanged = oldType !== acc.account_type;
    const balChanged = oldBal !== newBal;

    lines.push("✅ Akun diperbarui", "");
    lines.push(`${icon} ${nameChanged ? `${oldName} ➜ ${acc.account_name}` : acc.account_name}`);
    lines.push(`🏷️ Tipe: ${typeChanged ? `${oldType} ➜ ${acc.account_type}` : acc.account_type}`);
    lines.push(`💰 Saldo: ${balChanged ? `${rp(oldBal)} ➜ ${rp(newBal)}${deltaText}` : rp(newBal)}`);

    if (!nameChanged && !typeChanged && !balChanged) {
      lines.push("", "ℹ️ Datanya sama dengan sebelumnya, tidak ada yang berubah.");
    }

  } else if (action === "delete") {
    lines.push("🗑️ Akun dihapus", "");
    lines.push(`${icon} ${acc.account_name}`);
    lines.push(`🏷️ Tipe: ${acc.account_type}`);
    lines.push(`💰 Saldo terakhir: ${rp(acc.balance)}`);

  } else {
    lines.push("✅ Selesai");
  }

  return { json: { action, message: lines.join("\n") } };
});

