const updates = items.filter(i => i.action === 'update').map(i => ({ ...i }));
const rest = [];

for (const it of items) {
  if (it.action === 'update') continue;

  if (it.action === 'increase' || it.action === 'decrease') {
    const target = updates.find(u =>
      u.entity === it.entity && (same(u.name, it.name) || same(u.new_name, it.name))
    );
    if (target) {
      const signed = (it.action === 'increase' ? 1 : -1) * Number(it.amount ?? 0);
      target.amount_delta = Number(target.amount_delta ?? 0) + signed;
