// Guard against the model "helpfully" guessing: an account / savings name only counts if the user
// actually wrote it (the full name, or one word of it of 3+ letters, e.g. "bca" for "BCA Utama").
const userMsg = String($('Data Input').first().json.message || '').toLowerCase();
const mentioned = name => {
  if (!name) return null;
