  if (userMsg.includes(n)) return name;
  const words = n.split(/[^a-z0-9]+/).filter(w => w.length >= 3);
  return words.some(w => new RegExp(`(^|[^a-z0-9])${w}([^a-z0-9]|$)`).test(userMsg)) ? name : null;
};

// Budgets the user created (sent by Get All Data). Without database lookups here, these names are what the
// category has to match, because the database looks the budget up by name.
const budgetNames = (() => {
  try { return ($('Get All Data').first().json.budgets || []).map(b => b.category).filter(Boolean); } catch (e) { return []; }
})();
const findBudget = s => budgetNames.find(n => n.toLowerCase() === String(s || '').trim().toLowerCase()) || null;

// The parser picks a category KEY (food, shopping, ...) and should answer with the user's own budget name when
// one fits. If it only gave the key, look for a budget whose name belongs to that key.
const KEY_ALIAS = {
  health: 'health_and_fitness', fitness: 'health_and_fitness', sport: 'health_and_fitness', sports: 'health_and_fitness',
  gift: 'gifts_and_donations', gifts: 'gifts_and_donations', donation: 'gifts_and_donations', donations: 'gifts_and_donations',
  subscription: 'subscriptions', utilities: 'bills', bill: 'bills', groceries: 'food', dining: 'food',
  hobby: 'entertainment', hobbies: 'entertainment', pet: 'pets', housing: 'home', transportation: 'transport',
  personal_care: 'personal_care', misc: 'other', others: 'other'
