const KEY_BUDGET_WORDS = {
  food: ['food', 'makan', 'makanan', 'minum', 'kuliner', 'dining', 'groceries', 'jajan', 'kopi'],
  transport: ['transport', 'transportasi', 'bensin', 'ojek', 'parkir', 'kendaraan'],
  shopping: ['shopping', 'belanja', 'fashion', 'pakaian', 'baju', 'gadget', 'elektronik'],
  bills: ['bills', 'bill', 'tagihan', 'utilities', 'cicilan', 'listrik', 'internet'],
  health_and_fitness: ['health', 'kesehatan', 'fitness', 'gym', 'olahraga', 'sport', 'sports'],
  entertainment: ['entertainment', 'hiburan', 'hobi', 'hobby', 'game', 'games', 'leisure'],
  education: ['education', 'pendidikan', 'belajar', 'kursus', 'buku', 'sekolah'],
  personal_care: ['personal care', 'perawatan', 'skincare', 'beauty', 'salon'],
  home: ['home', 'rumah', 'kost', 'kos', 'sewa', 'household'],
  travel: ['travel', 'liburan', 'wisata', 'trip', 'jalan-jalan'],
  subscriptions: ['subscription', 'subscriptions', 'langganan', 'subs'],
  gifts_and_donations: ['gift', 'gifts', 'hadiah', 'donasi', 'donation', 'sedekah', 'zakat'],
  pets: ['pets', 'pet', 'hewan', 'kucing', 'anjing']
