function resolveCategory(type, v) {
  const s = clean(v);
  if (!s) return null;
  if (TYPE_ALIAS[String(type || '').trim().toLowerCase()] !== 'expenses') return s.toLowerCase();   // income categories stay free text
  const own = findBudget(s);
  if (own) return own;                                                  // already the name of one of the user's budgets
  const k = s.toLowerCase().replace(/\s*[&/]\s*/g, '_').replace(/[\s-]+/g, '_');   // "Health & Fitness" -> health_and_fitness
  const key = KEY_ALIAS[k] || k;
  const words = KEY_BUDGET_WORDS[key];
  if (words) {
    const hit = budgetNames.find(n => words.includes(n.toLowerCase()) || n.toLowerCase().split(/[^a-z0-9]+/).some(w => words.includes(w)));
    if (hit) return hit;                                               // key -> the user's budget for that key
  }
  return key;                                                          // no matching budget: the database rejects it and the reply says how to fix
}

// A budget the user chose themselves, e.g. "beli member gym 800rb pakai bca kategori entertainment"
// or "... masuk ke budget food". Only these phrases count; the word "budget" alone does not
// (so "buat budget gym 300rb" in the same message is not mistaken for a category).
function explicitBudget(msg) {
  const m = msg.match(/\b(?:kategori|category)\s+(?:nya\s+)?([a-z0-9&_-]+(?:\s+[a-z0-9&_-]+)?)/i)
         || msg.match(/\b(?:masuk(?:\s+ke)?|ke)\s+budget\s+([a-z0-9&_-]+(?:\s+[a-z0-9&_-]+)?)/i);
  if (!m) return null;
  const tail = m[1].trim().toLowerCase();
  const hit = budgetNames.filter(n => tail === n.toLowerCase() || tail.startsWith(n.toLowerCase() + ' '))
                         .sort((x, y) => y.length - x.length)[0];
  return hit || tail.split(' ')[0];
}
const explicit = explicitBudget(userMsg);

// Relative dates ("kemarin", "2 hari lalu", "yesterday") are resolved here from today's date (Asia/Jakarta),
// because the parser is told never to guess dates. Only used when the parser returned no date.
const DAY_LIMIT = 60;   // transactions can be recorded at most 60 days back
const TODAY = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Jakarta' }).format(new Date());   // YYYY-MM-DD
// 'too_old' / 'future' for a full YYYY-MM-DD date outside [today-60, today]; null if fine or unreadable
function dateProblem(s) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(s))) return null;
  const diff = (Date.parse(`${TODAY}T00:00:00Z`) - Date.parse(`${s}T00:00:00Z`)) / 86400000;
  if (!Number.isFinite(diff)) return null;
  return diff > DAY_LIMIT ? 'too_old' : (diff < 0 ? 'future' : null);
}
function relativeDate(msg) {
// Future words: "besok", "lusa", "tomorrow", "3 hari lagi", "2 hari ke depan", "in 3 days", "3 days from now"
if (
  /\b(besok|tomorrow)\b|(?<!kemarin )\blusa\b|\b\d+\s*hari\s+(?:lagi|ke\s+depan|dari\s+sekarang)\b|\bin\s+\d+\s+days?\b|\b\d+\s+days?\s+(?:from\s+now|later|ahead)\b/i.test(msg)
) return 'FUTURE';
  const hits = [];
  if (/\b(kemarin lusa|kemarin dulu|2 hari (?:yang )?lalu|day before yesterday)\b/.test(msg)) hits.push(2);
  else if (/\b(kemarin|kemaren|kmrn|yesterday)\b/.test(msg)) hits.push(1);
  for (const m of msg.matchAll(/\b(\d{1,2})\s*(hari|days?)\s*(?:yang\s*)?(?:lalu|ago)\b/g)) hits.push(Number(m[1]));
  // numbers written as words, Indonesian and English
  const WORDS = { dua: 2, tiga: 3, empat: 4, lima: 5, enam: 6, tujuh: 7, delapan: 8, sembilan: 9, sepuluh: 10,
                  one: 1, a: 1, an: 1, two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9, ten: 10 };
  const W = Object.keys(WORDS).join('|');
  for (const m of msg.matchAll(new RegExp(`\\b(${W})\\s+(?:hari|days?)\\s+(?:yang\\s+)?(?:lalu|ago)\\b`, 'g'))) hits.push(WORDS[m[1]]);
  for (const m of msg.matchAll(new RegExp(`\\b(${W}|\\d{1,2})\\s+(?:minggu|weeks?)\\s+(?:yang\\s+)?(?:lalu|ago)\\b`, 'g'))) hits.push((WORDS[m[1]] || Number(m[1])) * 7);
  for (const m of msg.matchAll(/\b(\d{1,2})\s*(hari|days?)\s*(?:yang\s*)?(?:lalu|ago)\b/g)) hits.push(Number(m[1]));
  if (/\bseminggu (?:yang )?lalu\b/.test(msg)) hits.push(7);
