  if (/\b(?:(?:\d{1,2}|se|a|one|two|three|dua|tiga|empat|lima|enam)\s*)?(?:bulan|tahun|months?|years?)\s+(?:yang\s+)?(?:lalu|ago)\b|\blast\s+(?:month|year)\b|\b(?:sebulan|setahun)\s+(?:yang\s+)?lalu\b/.test(msg)) return 'OLD';
