const INCOME_WORDS = [
  [/\b(gaji|gajian|salary|payroll)\b/, 'salary'],
  [/\b(bonus|thr)\b/, 'bonus'],
  [/\b(freelance|freelancer|honor|honorarium)\b/, 'freelance'],
  [/\b(komisi|commission)\b/, 'commission'],
  [/\b(dividen|dividend)\b/, 'dividend'],
  [/\b(bunga|interest)\b/, 'interest'],
  [/\b(hadiah|gift|angpao|angpau)\b/, 'gift'],
  [/\b(cuan|untung|profit|capital gain|investasi|saham|reksadana|crypto|kripto)\b/, 'investment'],
