    L.push(`🏦 ${r.to.name}: ${rp(r.to.before)} → ${rp(r.to.after)}`);

    L.push('');
    L.push(`📈 Pemasukan ${monthLabel(r.month_start)}: ${rp(r.month_income)}`);

    if (r.prev_month_income > 0) {
      L.push(`Bulan lalu: ${rp(r.prev_month_income)}`);
    }

    if (r.category_is_default) {
      L.push(`ℹ️ Sumber pemasukan tidak disebut, jadi dicatat sebagai "${String(r.category || 'other')}". Sebutkan sumbernya (gaji, bonus, investasi, dll.) supaya kategorinya tepat.`);
