    L.push(`💰 ${bold('Tabungan ' + s.name)}`)
    L.push(`${rp(s.current)}${s.target ? ` / ${rp(s.target)}${s.percent != null ? ` (${s.percent}%)` : ''}` : ''}`);

    if (s.target_date) {
