}

// ==================== REJECTION REASON ====================

function reason(r, inp) {
  const q = r.name ? `"${r.name}"` : '';

  switch (r.reason) {
    case 'bad_type':
      if (inp.date_error) {
        const c = new Date(`${todayWib}T00:00:00Z`); c.setUTCDate(c.getUTCDate() - 60);
        const cut = c.toISOString().slice(0, 10);
        return inp.date_error === 'future'
          ? `Tanggal ${inp.date_text} belum terjadi. Transaksi hanya bisa dicatat untuk hari ini atau sebelumnya.`
          : `Tanggal transaksi terlalu lama atau tidak jelas. Transaksi hanya bisa dicatat sampai 60 hari ke belakang (paling lama ${cut}). Tulis tanggal lengkap yang masih dalam batas itu, atau hitungan hari seperti "kemarin" atau "5 hari lalu".`;
      }
      return inp.unreadable
        ? 'Pesan tidak terbaca sebagai transaksi. Contoh: "makan 25rb pakai BCA".'
        : 'Jenis transaksi tidak dikenali.';

    case 'bad_amount':
      return 'Nominal tidak valid. Harus antara Rp1 dan Rp100.000.000.000 (100 miliar) per transaksi.';

    case 'from_account_missing':
      need.add('accounts');

      return inp.type === 'expenses'
        ? 'Akun pembayaran belum disebut. Contoh: "makan 30rb pakai BCA".'
        : inp.type === 'savings'
          ? 'Akun sumber belum disebut. Contoh: "tabung 500rb dari BCA".'
          : 'Akun asal belum disebut. Contoh: "transfer 100rb dari BCA ke OVO".';

    case 'to_account_missing':
      need.add('accounts');

      return inp.type === 'income'
        ? 'Akun penerima belum disebut. Contoh: "gaji masuk 10jt ke BCA".'
        : 'Akun tujuan belum disebut. Contoh: "transfer 100rb ke OVO".';

    case 'from_account_not_found':
    case 'to_account_not_found':
      need.add('accounts');
      return `Akun ${q} tidak ditemukan.`;

    case 'same_account':
      return `Akun asal dan tujuan sama (${r.name}).`;

    case 'category_budget_missing':
      need.add('budgets');
      help.push({ create: `buat budget ${r.suggest} ${short(inp.amount)}`, base: exampleBase(inp) });
      return `"${r.subject}" termasuk kategori ${r.label}, tapi budget-nya belum ada.`;

    case 'category_unknown':
      need.add('budgets');
      help.push({ base: exampleBase(inp) });
      return `Kategori untuk "${r.name}" belum bisa ditentukan.`;

    case 'explicit_budget_not_found':
      need.add('budgets');
      help.push({ create: `buat budget ${r.name} ${short(inp.amount)}`, base: exampleBase(inp) });
      return `Budget "${r.name}" belum ada.`;

    case 'budget_not_found': {
      need.add('budgets');
      if (!r.name || r.name === '(tanpa kategori)') {
        help.push({ base: exampleBase(inp) });
        return 'Kategori belum bisa ditentukan.';
      }
      const nice = String(r.name).replace(/_/g, ' ');
      help.push({ create: `buat budget ${nice} ${short(inp.amount)}`, base: exampleBase(inp) });
      return `Belum ada budget untuk "${nice}".`;
    }

    case 'savings_not_found':
      need.add('savings');
      return `Tabungan ${q} tidak ditemukan.`;

    case 'insufficient_funds':
      return `Saldo ${r.name} (${rp(r.balance)}) tidak cukup untuk ${rp(r.amount)}.`;

    default:
      return 'Transaksi tidak dapat diproses.';
  }
}

// ==================== PROCESS RESULTS ====================

results.forEach((row, i) => {
