txAll = Array.isArray(txAll) ? txAll : [];
const message = String($('Data Input').first().json.message || '').toLowerCase();
const num = v => Number(v) || 0;
const isDebt = t => ['credit_card', 'loan'].includes(t);

const accounts = snap.accounts || [];
const liquidTotal = accounts.filter(a => !isDebt(a.type)).reduce((s, a) => s + num(a.balance), 0);
const debtTotal = accounts.filter(a => isDebt(a.type)).reduce((s, a) => s + num(a.balance), 0);

const [Y, M, D] = String(snap.as_of).split('-').map(Number);
const daysInMonth = new Date(Y, M, 0).getDate();

const budgets = (snap.budgets || []).map(b => {
  const limit = num(b.limit), spent = num(b.spent), remaining = limit - spent;
