const reserved = budgets.reduce((s, b) => s + Math.max(b.remaining, 0), 0);   // an overspent budget reserves 0
const unallocated = liquidTotal - reserved;
const totalOver = budgets.reduce((s, b) => s + b.over_by, 0);

