const facts = {
  month: snap.month, as_of: snap.as_of, day_of_month: D, days_in_month: daysInMonth,
  liquid_total: liquidTotal, debt_total: debtTotal,
  liquid_accounts: accounts.filter(a => !isDebt(a.type)).map(a => ({ name: a.name, type: a.type, balance: num(a.balance) })),
  debt_accounts: accounts.filter(a => isDebt(a.type)).map(a => ({ name: a.name, type: a.type, balance: num(a.balance) })),
  glossary: {
