  unallocated_is_negative: unallocated < 0,
  what_if,
  other_budget: (budgets.find(b => /^(other|others|lainnya|lain-lain|misc)$/i.test(String(b.category).trim())) || {}).category || null   // a catch-all budget for one-off spending, if the user has one
};

// transactions of this month, summarised for the AI (the full list stays in tx_all for the app to print)
const thisMonth = txAll.filter(t => String(t.date).slice(0, 7) === snap.month);
const byCat = {};
thisMonth.filter(t => t.type === 'expenses').forEach(t => { byCat[t.category || '-'] = (byCat[t.category || '-'] || 0) + num(t.amount); });
facts.spending_by_category_this_month = Object.entries(byCat).sort((a, b) => b[1] - a[1]).map(([category, total]) => ({ category, total }));
facts.transaction_count_this_month = thisMonth.length;
facts.this_month = snap.this_month; facts.last_month = snap.last_month;   // income / expenses / savings totals from the database
facts.largest_expenses_this_month = thisMonth.filter(t => t.type === 'expenses').sort((a, b) => num(b.amount) - num(a.amount)).slice(0, 5)
  .map(t => ({ date: t.date, category: t.category, notes: t.notes, merchant: t.merchant, amount: num(t.amount), account: t.from_account }));
facts.recent_transactions = txAll.slice(0, 15).map(t => ({ date: t.date, type: t.type, amount: num(t.amount), category: t.category, notes: t.notes, merchant: t.merchant, from: t.from_account, to: t.to_account, savings: t.savings }));

// What the bot itself can do, so "cara ..." questions are answered from this and not from general knowledge
facts.bot_guide = {
  note: 'Answer how-to questions about this bot ONLY from this guide. If something is not here, say you are not sure and point to /help.',
  create: 'Awali dengan "buat" atau "bikin". Akun: nama, tipe (cash, bank, e-wallet, credit card, loan, other), saldo awal. Contoh: "buat akun BCA tipe bank saldo awal 5jt". Budget: nama kategori dan limit bulanan. Contoh: "buat budget food 500rb". Savings: nama, target, deadline opsional. Contoh: "buat savings dana darurat target 10jt deadline desember 2027".',
  update: 'Sebutkan jenis, nama, dan nilai barunya. Contoh: "ubah tipe akun Dompet jadi e-wallet", "naikkan budget food 600rb".',
  delete: 'Hapus satu per satu, sebutkan namanya. Hapus massal tidak didukung. Contoh: "hapus akun OVO", "hapus budget food".',
  record: 'Pengeluaran: "makan siang 50rb pakai BCA". Pemasukan: "gaji masuk 10jt ke BCA". Transfer: "transfer 500rb dari BCA ke OVO". Tabungan: "tabung 200rb dari BCA ke dana darurat". Nominal dan akun wajib disebut. Tanggal opsional, maksimal 60 hari ke belakang.',
  balance_change: 'Perubahan saldo bukan transaksi. Untuk uang masuk, catat sebagai pemasukan.',
  insights: 'Tanya saldo, budget, savings, atau minta rincian transaksi, misalnya "rincikan pengeluaran bulan ini". Bisa juga simulasi, misalnya "kalau aku beli laptop 10jt gimana?".',
  help: 'Ketik /help untuk panduan lengkap atau /start untuk cara kerja bot.'
};

return [{ json: { snapshot: snap, facts, tx_all: txAll } }];

// Prepare Log: one row per reply sent to the user. Nothing here changes the reply.
const g = name => { try { return $(name).first().json || {}; } catch (e) { return {}; } };
const trg = g('Telegram Trigger');
const isHelp = $json.is_help === true;
const intents = isHelp ? ['help'] : (g('Extract Intents').intents || []);
const reply = String($json.response || '');

const hasOk = /✅/.test(reply);
const hasWarn = /⚠️|🚨|TIDAK DICATAT|belum lengkap|tidak ditemukan|tidak valid|tidak ada yang berubah/i.test(reply);
const onlyInsight = isHelp || (intents.length > 0 && intents.every(i => i === 'financial_insight'));
const status = onlyInsight ? 'succeeded' : (hasOk && hasWarn ? 'mixed' : (hasWarn ? 'rejected' : 'succeeded'));

return {
  json: {
    update_id: trg.update_id ?? null,
    chat_id: trg.message?.from?.id ?? trg.message?.chat?.id ?? null,
    message: String(g('Data Input').message || trg.message?.text || '').slice(0, 1000),
    intents: intents.length ? intents : ['unmatched'],
    status,
    reply: reply.slice(0, 4000)
  }
};

conditions.leftValue:
={{ (() => {
  const m = String($json.message ?? '')
    .trim()
    .toLowerCase()
    .replace(/@\w+$/, '')
    .replace(/[?!.\s]+$/, '');

  const isCmd = /^(\/start|\/help|help|bantuan|panduan|cara pakai|cara menggunakan|cara penggunaan)$/.test(m);

  const isGreet = /^(halo+|hallo+|hai+|hi+|hello|hey|hei|permisi|assalamualaikum|selamat (pagi|siang|sore|malam))( (bot|kak|min|bro|sis))?$/.test(m);

  const isAbout = m.length <= 60 && /\bbisa apa\b|\bsiapa (kamu|kau|nama)|\bkamu siapa\b|\b(bot|aplikasi|app) (ini )?(itu )?apa\b|\bapa (itu |ini )?(bot|aplikasi|app)\b|who are you|what can you do|what do you do|\btentang (kamu|bot|aplikasi)\b|\bapa yang bisa kamu lakukan\b/.test(m);

  return !(isCmd || isGreet || isAbout);
})() }}
